const still = flow.get("ndiExampleStill");
if (!Buffer.isBuffer(still)) {
    msg.statusCode = 503;
    msg.headers = { "Content-Type": "text/plain", "Retry-After": "5", "Cache-Control": "no-store" };
    msg.payload = "No picture from the NDI source yet.";
    return msg;
}
msg.statusCode = 200;
msg.headers = { "Content-Type": "image/jpeg", "Cache-Control": "no-store" };
msg.payload = still;
return msg;
